import json, numpy as np
from scipy import stats, integrate

def compute_bf01(k, n, sigma):
    p_h0 = stats.binom.pmf(k, n, 0.5)

    def integrand(theta):
        p_pos = 1 / (1 + np.exp(-theta))
        p_neg = 1 / (1 + np.exp(theta))
        hn = stats.halfnorm.pdf(theta, scale=sigma)
        return (stats.binom.pmf(k, n, p_pos) + stats.binom.pmf(k, n, p_neg)) * hn / 2

    p_h1, _ = integrate.quad(integrand, 0, 10)
    return p_h0 / p_h1 if p_h1 > 0 else float('inf')

results = {}
configs = {
    "pooled": (192, 348),
    "formality_only": (99, 176),
    "verbosity_only": (93, 172)
}

for name, (k, n) in configs.items():
    bf = {}
    for sigma in [0.3, 0.5, 1.0]:
        bf[f"sigma_{sigma}"] = round(compute_bf01(k, n, sigma), 4)

    p_hat = round(k/n, 4)

    # Interpret pooled
    bf_mid = bf["sigma_0.5"]
    if bf_mid > 10:
        interp = "strong evidence for null"
    elif bf_mid > 3:
        interp = "moderate evidence for null"
    elif bf_mid > 1:
        interp = "anecdotal evidence for null"
    else:
        interp = "evidence against null"

    results[name] = {
        "k": k, "n": n, "p_hat": p_hat,
        "bf01": bf,
        "interpretation": interp
    }

# Sensitivity conclusion
pooled_bfs = results["pooled"]["bf01"]
sens = []
for s in ["sigma_0.3", "sigma_0.5", "sigma_1.0"]:
    v = pooled_bfs[s]
    sens.append(f"{s}={v}")

results["sensitivity_conclusion"] = (
    f"Pooled BF01 across priors: {', '.join(sens)}. "
    f"Results are {'robust' if all(v > 1 for v in pooled_bfs.values()) else 'mixed'} across prior widths."
)

print(json.dumps(results, indent=2))

with open("/home/ubuntu/.agent-ml-research-idea_gen_0514_5/projects/causal_style_decomp_judge/artifacts/r16_analysis/claude_bayesian_equivalence.json", "w") as f:
    json.dump(results, f, indent=2)

